'{"childId":"00000000-0000-4000-8000-000000003621","grade":5,"title":"Tekrar","purpose":"practice","format":"practice","subjects":["Matematik"],"topics":[],"target":2,"minutes":null,"difficulty":"orta","kind":"mixed","note":"","step":2,"blocks":[]}');
create function pg_temp.source() returns jsonb language sql as $$select public.get_repeat_calendar('00000000-0000-4000-8000-000000003901')$$;
create function pg_temp.items(d int default 1) returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('day',d,'title','Birlikte tekrar','notes','Çözümü konuşup farklı bir örnek deneyin.','starts_at',now()+make_interval(days=>d),'minutes',15))$$;
create function pg_temp.apply(req uuid default '00000000-0000-4000-8000-000000006301',hash text default current_setting('test.hash'),items jsonb default pg_temp.items(),questions uuid[] default array['00000000-0000-4000-8000-000000003702'::uuid]) returns jsonb language sql as $$select public.apply_repeat_calendar(req,'00000000-0000-4000-8000-000000003901',hash,questions,items)$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"parent"}}',true);
select set_config('test.hash',pg_temp.source()->>'hash',true);
select is(jsonb_array_length(pg_temp.source()->'questions'),2,'only wrong choices and parent-reviewed partial work are eligible');
select ok(pg_temp.source()::text not like '%Expected%' and pg_temp.source()::text not like '%correct_key%','source does not expose answer keys');
select throws_ok($$select public.get_repeat_calendar(gen_random_uuid())$$,'42501','forbidden','unknown attempt concealed');
select throws_ok($$select pg_temp.apply(hash=>'stale')$$,'P0001','repeat_changed','changed review cannot be silently scheduled');
select throws_ok($$select pg_temp.apply(questions=>array['00000000-0000-4000-8000-000000003703'::uuid])$$,'P0001','repeat_ineligible','AI-only score excluded');
select throws_ok($$select pg_temp.apply(questions=>array['00000000-0000-4000-8000-000000003702'::uuid,'00000000-0000-4000-8000-000000003702'::uuid])$$,'P0001','invalid_input','duplicate selection rejected');
select throws_ok($$select pg_temp.apply(items=>pg_temp.items(4))$$,'P0001','invalid_input','at most three steps');
select throws_ok($$select pg_temp.apply(items=>pg_temp.items()||pg_temp.items())$$,'P0001','invalid_input','duplicate day rejected');
select throws_ok($$select pg_temp.apply(items=>pg_temp.items()||jsonb_set(pg_temp.items(),'{0,day}','2'))$$,'P0001','plan_overlap','overlapping selected reminders roll back atomically');
select throws_ok($$select pg_temp.apply(items=>jsonb_set(pg_temp.items(),'{0,starts_at}',to_jsonb((now()-interval '2 days')::text)))$$,'P0001','invalid_input','past dates rejected');
select throws_ok($$select pg_temp.apply(items=>jsonb_set(pg_temp.items(),'{0,starts_at}','"infinity"'))$$,'P0001','invalid_input','infinite time rejected');
reset role;
select is((select count(*)::int from gina.repeat_calendar_batches),0,'invalid requests leave no batches');
select is((select count(*)::int from public.events),0,'invalid requests leave no calendar rows');
set local role authenticated;
select is(jsonb_array_length(pg_temp.apply()->'items'),1,'one selected day applied');
select set_config('test.event',pg_temp.apply()#>>'{items,0,event_id}',true);
select is(jsonb_array_length(pg_temp.apply()->'items'),1,'lost reply replays exact result');
select throws_ok($$select pg_temp.apply(items=>pg_temp.items(2))$$,'P0001','request_conflict','same key cannot change schedule');
select throws_ok($$select pg_temp.apply(req=>gen_random_uuid())$$,'P0001','repeat_applied','another request cannot duplicate the same cycle');
select is(jsonb_array_length(pg_temp.source()#>'{scheduled,items}'),1,'scheduled dates readable from original attempt');
select is(pg_temp.source()#>>'{scheduled,questions,0,position}','2','saved plan retains exact original source question position');
select is(public.get_repeat_calendar_event((pg_temp.apply()#>>'{items,0,event_id}')::uuid)->>'attempt_id','00000000-0000-4000-8000-000000003901','calendar links back to original attempt');
select is(public.get_repeat_calendar_event(gen_random_uuid()),null,'unrelated event has no source link');
select throws_ok($$select * from gina.repeat_calendar_batches$$,'42501',null,'raw source links are private');
reset role;
select is((select count(*)::int from public.events),1,'retry creates one calendar event');
savepoint reassign_event;
update public.events set child_id=null;
select is((select event_id from gina.repeat_calendar_items),null,'explicit reassignment detaches original child review link');
select is((select count(*)::int from public.events),1,'reassignment preserves the calendar event');
rollback to savepoint reassign_event;
savepoint child_cleanup;
delete from public.children where id='00000000-0000-4000-8000-000000003621';
select is((select count(*)::int from public.events),0,'child deletion removes linked reminders instead of exposing them to entire family');
rollback to savepoint child_cleanup;
select is((select count(*)::int from public.exams),4,'no exam assigned');
select is((select status from public.exam_attempts where id='00000000-0000-4000-8000-000000003901'),'submitted','attempt state unchanged');
update public.exam_answers set score=100 where question_id='00000000-0000-4000-8000-000000003704';
set local role authenticated;
select isnt(pg_temp.source()->>'hash',current_setting('test.hash'),'review update changes source signature');
select is(jsonb_array_length(pg_temp.apply()->'items'),1,'completed receipt remains recoverable after later review changes');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003602","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003612","role":"parent"}}',true);
select throws_ok($$select pg_temp.source()$$,'42501','forbidden','other family cannot read source');
select is(public.get_repeat_calendar_event(current_setting('test.event')::uuid),null,'other family cannot read event source');
select throws_ok($$select pg_temp.apply()$$,'42501','forbidden','other family cannot apply source');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"device","child_id":"00000000-0000-4000-8000-000000003621"}}',true);
select throws_ok($$select pg_temp.apply()$$,'42501','forbidden','child cannot schedule repeats');
reset role;
delete from public.events;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"parent"}}',true);
select is(pg_temp.source()#>>'{scheduled,items,0,event_id}',null,'deleted reminder is visibly removed, never silently recreated');
select is(jsonb_array_length(pg_temp.apply()->'items'),1,'replaying completed receipt does not recreate deleted event');
reset role;
select is((select count(*)::int from public.events),0,'deleted event stays deleted');
select lives_ok($$delete from public.families where id='00000000-0000-4000-8000-000000003611';set constraints all immediate$$,'family cleanup succeeds');
select is((select count(*)::int from gina.repeat_calendar_batches),0,'source links removed on family deletion');
select ok(not has_function_privilege('anon','public.apply_repeat_calendar(uuid,uuid,text,uuid[],jsonb)','EXECUTE'),'anonymous write blocked');
select * from finish();rollback;
